"""Small standalone scientific display; caller supplies authenticated views.

Import is inert. render(payload) performs JSON/HTML work only: no file reads,
NumPy, native data, field/ROI statistics, browser, networking or research work.
The root owner must authenticate all input/provenance and validate real output.
"""
import base64
import hashlib
import html
import json
import math
import re

MAX_HTML_BYTES=8_200_000
MAX_JSON_BYTES=8_000_000
SCHEMA='task1-native-GUI-append-E13fine-display-v1'
FIELDS=('AM_max2074','carrier_RMS','contact_J')
REPOSITORY='yoodohyun-codex-cloud/ngg-tis-task1'


def _require(ok,message):
    if not ok:raise ValueError(message)


def _has_fill_geometry(pad):
    if not isinstance(pad,dict):return False
    rectangles=pad.get('patch_rectangles_mm')
    if isinstance(rectangles,list)and rectangles:
        return all(isinstance(r,list)and len(r)==4 and all(type(v)in(int,float)and math.isfinite(v)for v in r)and r[0]<r[1]and r[2]<r[3]for r in rectangles)
    def polygon_valid(points):
        if not(isinstance(points,list)and len(points)>=3 and all(isinstance(v,list)and len(v)==2 and all(type(x)in(int,float)and math.isfinite(x)for x in v)for v in points)):return False
        area2=sum(a[0]*b[1]-b[0]*a[1]for a,b in zip(points,points[1:]+points[:1]));return math.isfinite(area2)and abs(area2)>0
    holes=pad.get('holes_xy_mm',[])
    return polygon_valid(pad.get('polygon_xy_mm'))and isinstance(holes,list)and all(polygon_valid(hole)for hole in holes)


def _validate(payload):
    _require(isinstance(payload,dict)and isinstance(payload.get('sections'),list)and len(payload['sections'])==2,'Exactly two separate native/legacy grid sections required')
    sections=payload['sections'];kinds=[section.get('kind')for section in sections]
    _require(kinds==['new_native','legacy_reference'],'Explicit ordered new_native/legacy_reference kinds; no mixed-grid ranking section')
    _require(len(sections[0].get('cases',[]))==4 and len(sections[1].get('cases',[]))==4,'Exactly four new cases plus four legacy reference cases; never silently omit data to fit')
    ranges=payload.get('shared_initial_ranges',{})
    for name in('x_mm','y_mm','depth_mm','AM_V_m','RMS_V_m','J_A_m2','bar_value','wave_time_ms','wave_voltage_V'):
        pair=ranges.get(name)
        _require(isinstance(pair,(list,tuple))and len(pair)==2 and all(type(v)in(int,float)and math.isfinite(v)for v in pair)and pair[0]<pair[1],'Explicit finite increasing shared initial range '+name)
    modes=payload.get('normalization_modes')
    _require(isinstance(modes,list)and modes and all(isinstance(m,dict)and isinstance(m.get('id'),str)and m['id']for m in modes),'Explicit normalization mode IDs')
    _require(len({m['id']for m in modes})==len(modes),'Unique normalization IDs')
    bars=payload.get('bar_metrics')
    _require(isinstance(bars,list)and bars and all(isinstance(m,dict)and isinstance(m.get('id'),str)and m['id']and isinstance(m.get('unit'),str)for m in bars),'Explicit stored-stat bar metrics and units')
    _require(len({m['id']for m in bars})==len(bars),'Unique stored-stat bar metric IDs')
    _require([c.get('pad_count')for c in sections[1]['cases']]==[4,8,12,16],'Always preserve ordered legacy 4/8/12/16 reference row and 4-pad baseline')
    strict_total=extrap_total=probe_total=0
    for section in sections:
        _require(isinstance(section.get('cases'),list)and len({c.get('id')for c in section['cases']})==len(section['cases']),'Unique source case IDs within each grid section')
        for case in section['cases']:
            _require(isinstance(case,dict)and isinstance(case.get('id'),str)and isinstance(case.get('display'),dict),'Case ID and authenticated display required')
            _require(case.get('independent_outputs')==2,'Published two-output/common-return datasets only')
            if section['kind']=='new_native':
                _require(case.get('pad_count')==4,'New native cases retain four physical pads and two outputs')
                probe=case.get('probe_summary')
                _require(isinstance(probe,dict)and isinstance(probe.get('probes'),list)and probe.get('probe_count')==len(probe['probes'])==40,'Actual forty-row probe payload for every new native case')
                counts=[probe.get(k)for k in('calculated_probe_count','unavailable_probe_count','strict_same_layer_bracket_available_probe_count','same_layer_extrapolated_probe_count')]
                _require(all(type(n)is int and 0<=n<=40 for n in counts)and counts[0]==40 and counts[1]==0 and counts[2]+counts[3]==40,'Explicit actual strict/extrapolated/unavailable probe counts, not missing-as-zero')
                rows=probe['probes'];_require(len({r.get('probe_id')for r in rows})==40,'Forty unique physical probe IDs')
                _require(all(r.get('status')=='calculated_unloaded_only'and type(r.get('strict_same_layer_bracket_available'))is bool and type(r.get('same_layer_extrapolation_used'))is bool and r['strict_same_layer_bracket_available']!=r['same_layer_extrapolation_used']for r in rows),'Each actual probe explicitly identifies strict bracket or same-layer extrapolation')
                _require(sum(r['strict_same_layer_bracket_available']for r in rows)==counts[2]and sum(r['same_layer_extrapolation_used']for r in rows)==counts[3],'Probe row flags match original summary counts')
                for row in rows:
                    unloaded=row.get('unloaded')
                    _require(isinstance(unloaded,dict)and all(type(unloaded.get(k))in(int,float)and math.isfinite(unloaded[k])for k in('carrier_waveform_Vpp','carrier_waveform_N65536_Vpp','carrier_RMS_exact_V','envelope_AM_exact_V_peak','physical_voltage_10Hz_DFT_peak_V','envelope_10Hz_DFT_peak_V')),'Original double-N/RMS/spectrum probe metrics, not reconstructed display values')
                    wave=row.get('waveform')or probe.get('waveforms_by_probe_id',{}).get(row['probe_id'])
                    _require(isinstance(wave,dict),'Bounded actual stored waveform excerpts for all160 new probes')
                    for tkey,vkey in(('carrier_excerpt_time_s','carrier_excerpt_V'),('envelope_time_s','envelope_V')):
                        ts=wave.get(tkey);vs=wave.get(vkey)
                        _require(isinstance(ts,list)and isinstance(vs,list)and 0<len(ts)==len(vs)<=128 and all(type(v)in(int,float)and math.isfinite(v)for v in ts+vs),'At most128 actual finite points per waveform/envelope excerpt')
                probe_total+=40;strict_total+=counts[2];extrap_total+=counts[3]
            artifacts=case.get('provenance',{}).get('artifacts',[])
            _require(isinstance(artifacts,list),'Optional native artifact links are explicit metadata entries')
            for artifact in artifacts:
                path=artifact.get('repo_relative_path')if isinstance(artifact,dict)else None
                _require(isinstance(path,str)and path and not path.startswith('/')and '\\'not in path and ':'not in path and all(part not in('', '.', '..')for part in path.split('/')),'Safe repository-relative artifact path, no absolute/private traversal')
                _require(re.fullmatch('[0-9a-f]{40}',artifact.get('fixed_commit',''))is not None and re.fullmatch('[0-9a-f]{64}',artifact.get('SHA256',''))is not None and type(artifact.get('bytes'))is int and artifact['bytes']>=0,'Fixed artifact commit, SHA256 and byte count metadata; existence is not inferred')
            for value in case.get('amplitude_scales',{}).values():
                _require(type(value)in(int,float)and math.isfinite(value)and value>=0,'Published finite nonnegative amplitude scale only')
            for values in case.get('bar_values',{}).values():
                _require(isinstance(values,dict)and all(type(value)in(int,float)and math.isfinite(value)for value in values.values()),'Stored normalized bar values are finite caller-provided statistics')
            for variable,planes in case['display'].get('planes',{}).items():
                _require(variable in FIELDS and isinstance(planes,dict),'Only stored AM/carrier RMS/contact J display planes')
                if variable=='contact_J':
                    _require(planes.get('status')in('unavailable','stored_native_map'),'Explicit stored/unavailable contact J status')
                    if planes['status']=='unavailable':
                        _require('xy'not in planes,'Unavailable contact J must not contain a fabricated map');continue
                    _require(isinstance(planes.get('xy'),dict)and isinstance(case['display'].get('pad_outlines'),list)and case['display']['pad_outlines']and all(_has_fill_geometry(pad)for pad in case['display']['pad_outlines']),'Stored native contact J map and physical footprint clipping geometry required');planes={'xy':planes['xy']}
                for plane in planes.values():
                    _require(isinstance(plane,dict)and plane.get('display_only')is True,'Every supplied plane is display-only; original scientific statistics stay separate')
                    shape=plane.get('shape');he=plane.get('h_edges_mm');ve=plane.get('v_edges_mm')
                    _require(isinstance(shape,list)and len(shape)==2 and all(type(n)is int and 0<n<=512 for n in shape),'Bounded explicit plane shape')
                    _require(isinstance(he,list)and isinstance(ve,list)and len(he)==shape[1]+1 and len(ve)==shape[0]+1,'Actual physical plane edges match shape')
                    _require(all(type(v)in(int,float)and math.isfinite(v)for v in he+ve)and all(a<b for a,b in zip(he,he[1:]))and all(a<b for a,b in zip(ve,ve[1:])),'Strictly increasing physical edges')
                    _require(isinstance(plane.get('values_b64_float16LE'),str)and isinstance(plane.get('valid_mask_b64_u8'),str),'Float16 display values and explicit validity mask required')
                    _require(plane.get('horizontal_axis')in('x_mm','y_mm')and plane.get('vertical_axis')in('x_mm','y_mm','depth_mm'),'Explicit physical axes required')
                    if plane.get('arrows'):_require(plane.get('arrow_frequency_Hz')==2000 and plane.get('arrow_phase_rad')==0,'Arrows are signed real carrier E at2000Hz phase0, never AM vectors')
    _require((probe_total,strict_total,extrap_total)==(160,80,80),'All160 actual new probes: strict80 and explicit same-layer extrapolation80')
    return modes


